# FILE: Chart.yaml
apiVersion: v2
name: stateful-app
description: A Helm chart for a stateful application with pre-install DB migration job, StatefulSet, headless Service, and PVC
type: application
version: 0.1.0
appVersion: "1.0.0"
kubeVersion: ">=1.22.0-0"
home: https://example.com/stateful-app
sources:
  - https://example.com/stateful-app/repo
maintainers:
  - name: DevOps Team
    email: devops@example.com
icon: https://example.com/icon.png
---
# FILE: values.yaml
nameOverride: ""
fullnameOverride: ""

replicaCount: 3

image:
  repository: ghcr.io/example/stateful-app
  tag: "1.0.0"
  pullPolicy: IfNotPresent
  pullSecrets: []
  # - name: my-regcred

serviceAccount:
  create: true
  name: ""
  annotations: {}

podAnnotations: {}
podLabels: {}

podSecurityContext:
  runAsNonRoot: true
  runAsUser: 10001
  runAsGroup: 10001
  fsGroup: 10001
  seccompProfile:
    type: RuntimeDefault

securityContext:
  allowPrivilegeEscalation: false
  readOnlyRootFilesystem: true
  runAsNonRoot: true
  capabilities:
    drop:
      - ALL

service:
  port: 8080
  annotations: {}
  headless:
    annotations: {}

persistence:
  enabled: true
  storageClass: ""
  accessModes:
    - ReadWriteOnce
  size: 10Gi
  mountPath: /var/lib/stateful-app

db:
  host: "db"
  port: 5432
  name: "appdb"
  user: "appuser"
  sslMode: "disable"
  existingSecret: ""
  secretKeys:
    password: "password"
  # If existingSecret is empty and password is provided below, a Secret will be created
  password: ""

env: []
# - name: APP_LOG_LEVEL
#   value: info

envFrom: []
# - secretRef:
#     name: another-secret
# - configMapRef:
#     name: my-config

resources:
  requests:
    cpu: 100m
    memory: 256Mi
  limits:
    cpu: 500m
    memory: 512Mi

migrate:
  enabled: true
  annotations: {}
  image:
    repository: ghcr.io/example/stateful-app
    tag: "1.0.0"
    pullPolicy: IfNotPresent
  command: ["/bin/sh", "-c"]
